version: "1"
routes:
  /:
    description: The site's home page served natively from public/index.html.
    page:
      file: public/index.html
      cacheControl: no-cache
  /assets/*:
    description: Every file under public/assets, with a directory index and one-hour caching.
    static:
      directory: public/assets
      index: index.html
      cacheControl: public, max-age=3600
  /api/info:
    description: A small JSON endpoint next to the static site, computed by a trusted function.
    function:
      source: functions/info.mjs
      args:
        name: Example site
        version: "1"
    # Why this route runs trusted. Keep it when you add a function that
    # touches the filesystem: that needs a trusted route, and a body policy
    # makes `audit` ask for this line.
    sandboxReason: Reviewed first-party code; trusted deliberately.
    response:
      headers:
        Cache-Control: no-store
export default function info(request, {args}) {
  return Response.json({name: args.name, version: args.version});
}
